import Card from "@mui/material/Card";
import CardContent from "@mui/material/CardContent";
import Typography from "@mui/material/Typography";

import Grid from "@mui/material/Grid";

import CheckIcon from "@mui/icons-material/Check";
import IconButton from "@mui/material/IconButton";

export default function Todo() {
  return (
    <>
      <Card
        sx={{
          minWidth: 275,
          backgroundColor: "#083880",
          color: "#fff",
          marginTop: "30px",
        }}
      >
        <CardContent>
          <Grid container spacing={2}>
            <Grid size={8}>
              {" "}
              <Typography variant="h5" sx={{ textAlign: "right" }}>
                المهمه الاولي
              </Typography>
            </Grid>

            {/* Action Buttons */}
            <Grid
              size={4}
              container
              display="flex"
              justifyContent="space-around"
              alignItems="center"
            >
              <IconButton
                aria-label="delete"
                style={{
                  backgroundColor: "#fff",
                  color: "#08bc34a",
                  border: "3px solid #08bc34",
                }}
              >
                <CheckIcon />
              </IconButton>

              <IconButton
                aria-label="delete"
                style={{
                  backgroundColor: "#fff",
                  color: "#08bc34a",
                  border: "3px solid #08bc34",
                }}
              >
                <CheckIcon />
              </IconButton>

              <IconButton
                aria-label="delete"
                style={{
                  backgroundColor: "#fff",
                  color: "#08bc34a",
                  border: "3px solid #08bc34",
                }}
              >
                <CheckIcon />
              </IconButton>
            </Grid>
          </Grid>
        </CardContent>
      </Card>
    </>
  );
}
